// PDL — Movimiento behaviors (generated by scripts/build-css-index.mjs from
// design-system/registry/families.json). Pair it with css/family/motion.
// Activates motion; initPDL() activates every family.
import { initPageMotion } from "../motion.js";
import { initCursor } from "../cursor.js";

export function initFamily(options = {}) {
  const root = options.root ?? document;
  const instances = [
    initPageMotion(root),
    initCursor({ root, enabled: options.cursor !== false }),
  ];
  return {
    destroy() {
      for (const instance of instances.reverse()) instance?.destroy?.();
    }
  };
}
